// v14.3: validate technician at ingress and carry it through the PDF loop.
const incoming = $input.first().json;
const data = incoming.body ?? incoming;
const normalize = v => Array.isArray(v) ? String(v[0] ?? '').trim() : String(v ?? '').trim();
const fields = data.namedValues ?? data.named_values ?? data.form_response ?? data;
const tech = normalize(data.technician || data.nama_teknisi || data['Nama Teknisi'] || data['Nama teknisi'] || data['Technician'] || fields.technician || fields.nama_teknisi || fields['Nama Teknisi'] || fields['Nama teknisi'] || fields['Technician']);
if (!tech) throw new Error('TECHNICIAN_MISSING_AT_WEBHOOK: Google Form sender must include Nama Teknisi in webhook JSON. No fallback technician is allowed.');
let files = data.file_ids ?? data.files ?? [];
if (typeof files === 'string') files = files.split(',').map(s=>s.trim()).filter(Boolean);
if (!Array.isArray(files) || files.length===0) throw new Error('FILE_IDS_MISSING: Google Form webhook must send file_ids array');
if (files.length>30) throw new Error('MAX_30_PDFS');
const seen=new Set(), out=[];
for(const f of files){
  const id=normalize(typeof f==='object' ? (f.id ?? f.file_id) : f);
  if(!/^[A-Za-z0-9_-]{10,}$/.test(id)) throw new Error('INVALID_PDF_FILE_ID: '+id);
  if(seen.has(id)) continue;
  seen.add(id);
  out.push({
    json:{
      file_id:id,
      file_name:typeof f==='object'?normalize(f.name):'',
      submission_id:data.submission_id??'',
      technician:tech,
      enable_pdf:false
    }
  });
}
return out;

// v14.7: Robust PLN OCR Extraction, Intelligent Auto-Sanitizer, and Inversion Self-Correction
const source = $input.item.json || {};
const keys = [
  'id_pelanggan', 'nama_pelanggan', 'jatuh_tempo_bulan',
  'jatuh_tempo_tahun', 'total_harus_dibayar',
  'stand_akhir_lwbp', 'stand_akhir_wbp',
  'stand_awal_lwbp', 'stand_awal_wbp',
  'stand_akhir_kvarh', 'stand_awal_kvarh'
];
const targetKeys = new Set(keys);
const candidates = [];
const examined = new WeakSet();
const issues = [];
const priority = [
  'text', 'output', 'response', 'result', 'content', 'parts',
  'data', 'candidates', 'message', 'generations', 'choices', 'json'
];

function parseEmbeddedJson(text) {
  if (typeof text !== 'string') return null;
  let clean = text.trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  }
  try { return JSON.parse(clean); } catch (e) { /* continue */ }
  const start = clean.indexOf('{');
  if (start < 0) return null;
  let depth = 0, quoted = false, slash = false;
  for (let i = start; i < clean.length; i++) {
    const ch = clean[i];
    if (quoted) {
      if (slash) slash = false;
      else if (ch === '\\') slash = true;
      else if (ch === '"') quoted = false;
      continue;
    }
    if (ch === '"') quoted = true;
    else if (ch === '{') depth++;
    else if (ch === '}' && --depth === 0) {
      try { return JSON.parse(clean.slice(start, i + 1)); } catch (e) { return null; }
    }
  }
  return null;
}

function explore(node, path, depth) {
  if (depth > 10 || node === null || node === undefined) return;
  if (typeof node === 'string') {
    const parsed = parseEmbeddedJson(node);
    if (parsed !== null) explore(parsed, path + ' [JSON text]', depth + 1);
    return;
  }
  if (typeof node !== 'object') return;
  if (examined.has(node)) return;
  examined.add(node);
  if (Array.isArray(node)) {
    for (let i = 0; i < Math.min(node.length, 20); i++) explore(node[i], `${path}[${i}]`, depth + 1);
    return;
  }
  const matches = keys.filter(k => Object.prototype.hasOwnProperty.call(node, k));
  if (matches.length) candidates.push({ data: node, path, matched: matches.length });
  for (const key of priority) {
    if (Object.prototype.hasOwnProperty.call(node, key)) explore(node[key], `${path}.${key}`, depth + 1);
  }
  for (const [key, value] of Object.entries(node)) {
    if (!priority.includes(key) && !targetKeys.has(key) && typeof value === 'object') {
      explore(value, `${path}.${key}`, depth + 1);
    }
  }
}

explore(source, '$json', 0);
candidates.sort((a, b) => b.matched - a.matched);
const best = candidates[0] || null;
const extracted = best ? best.data : {};
const rec = {};
for (const k of keys) rec[k] = Object.prototype.hasOwnProperty.call(extracted, k) ? extracted[k] : null;

if (!best) issues.push('Gemini response did not contain recognizable OCR JSON fields');

// 1. Clean Customer ID
if (rec.id_pelanggan !== null) {
  rec.id_pelanggan = String(rec.id_pelanggan).replace(/[^0-9]/g, '');
  if (!/^\d{10,13}$/.test(rec.id_pelanggan)) issues.push('Invalid customer ID (must be 10-13 digits)');
} else {
  issues.push('Missing id_pelanggan');
}

// 2. Clean Customer Name
if (rec.nama_pelanggan !== null) {
  rec.nama_pelanggan = String(rec.nama_pelanggan).trim();
  if (!rec.nama_pelanggan) issues.push('Missing customer name');
} else {
  issues.push('Missing nama_pelanggan');
}

// 3. Clean Due Year & Month
if (rec.jatuh_tempo_tahun !== null) {
  rec.jatuh_tempo_tahun = Number(String(rec.jatuh_tempo_tahun).replace(/[^0-9]/g, ''));
  if (!Number.isInteger(rec.jatuh_tempo_tahun) || rec.jatuh_tempo_tahun < 2000 || rec.jatuh_tempo_tahun > 2100) {
    issues.push('Invalid due year');
  }
} else {
  issues.push('Missing jatuh_tempo_tahun');
}

const months = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const alias = {jan:1,january:1,januari:1,feb:2,february:2,februari:2,mar:3,march:3,maret:3,apr:4,april:4,may:5,mei:5,jun:6,june:6,juni:6,jul:7,july:7,juli:7,aug:8,august:8,agustus:8,agu:8,sep:9,sept:9,september:9,oct:10,okt:10,oktober:10,nov:11,november:11,dec:12,des:12,desember:12};
if (rec.jatuh_tempo_bulan !== null) {
  const raw = String(rec.jatuh_tempo_bulan).trim().toLowerCase();
  const index = /^\d{1,2}$/.test(raw) ? Number(raw) : months.findIndex(m => m.toLowerCase() === raw) + 1 || alias[raw];
  if (!Number.isInteger(index) || index < 1 || index > 12) issues.push('Invalid due month');
  else rec.jatuh_tempo_bulan = months[index - 1];
} else {
  issues.push('Missing jatuh_tempo_bulan');
}

// 4. Clean Total Payable
if (rec.total_harus_dibayar !== null) {
  const cleanTotal = String(rec.total_harus_dibayar).replace(/[^0-9]/g, '');
  rec.total_harus_dibayar = cleanTotal ? Number(cleanTotal) : NaN;
  if (!Number.isSafeInteger(rec.total_harus_dibayar) || rec.total_harus_dibayar <= 0) {
    issues.push('Invalid total payable');
  }
} else {
  issues.push('Missing total_harus_dibayar');
}

// 5. Intelligent Meter Reading Sanitizer (Handles Indonesian and Anglo number formats)
function sanitizeMeter(val) {
  if (val === null || val === undefined) return null;
  let s = String(val).trim().replace(/\s+/g, '');
  if (!s) return null;
  // Format: 24.514,962 -> 24514.962 (Indonesian)
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) {
    s = s.replace(/\./g, '').replace(',', '.');
  }
  // Format: 24,514.962 -> 24514.962 (Anglo)
  else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) {
    s = s.replace(/,/g, '');
  }
  // Format: 24514,962 -> 24514.962
  else if (/^\d+,\d+$/.test(s)) {
    s = s.replace(',', '.');
  }
  return s;
}

for (const k of keys.filter(k => k.startsWith('stand_'))) {
  rec[k] = sanitizeMeter(rec[k]);
  if (rec[k] === null || !/^\d+(\.\d+)?$/.test(rec[k])) {
    issues.push('Invalid meter reading ' + k);
  }
}

// 6. Cross-Check: Stand Akhir vs Stand Awal Consistency
const meterPairs = [
  ['stand_akhir_lwbp', 'stand_awal_lwbp', 'LWBP'],
  ['stand_akhir_wbp', 'stand_awal_wbp', 'WBP'],
  ['stand_akhir_kvarh', 'stand_awal_kvarh', 'kVARh']
];

let invertedCount = 0;
for (const [akhirKey, awalKey] of meterPairs) {
  const akhir = parseFloat(rec[akhirKey]);
  const awal = parseFloat(rec[awalKey]);
  if (!isNaN(akhir) && !isNaN(awal) && akhir < awal) {
    invertedCount++;
  }
}

// Auto-repair if OCR inverted Row 1 and Row 2
if (invertedCount >= 2) {
  for (const [akhirKey, awalKey] of meterPairs) {
    const tmp = rec[akhirKey];
    rec[akhirKey] = rec[awalKey];
    rec[awalKey] = tmp;
  }
  rec._ocr_warning = 'AUTO_CORRECTED_INVERTED_STAND_TABLE_ROWS';
}

// 7. Inherit metadata safely from sequential splitter
let meta = {};
try {
  const seq = $('Process PDFs Sequentially').item.json || {};
  const dl = $('Download PDF').item.json || {};
  meta = {
    file_id: seq.file_id || dl.id || dl.file_id,
    file_name: seq.file_name || dl.name || dl.file_name,
    submission_id: seq.submission_id || '',
    technician: seq.technician || ''
  };
} catch (e) {
  issues.push('Unable to link source PDF metadata: ' + e.message);
}

return {
  json: {
    processed_at: new Date().toISOString(),
    file_id: meta.file_id || null,
    file_name: meta.file_name || null,
    submission_id: meta.submission_id || null,
    technician: meta.technician || null,
    ocr_status: issues.length ? 'NEEDS_REVIEW' : 'VALID',
    ...rec,
    validation_errors: issues,
    ocr_debug: {
      gemini_output_keys: Object.keys(source),
      matched_field_count: best?.matched || 0,
      parsed_from: best?.path || null
    }
  }
};

const raw = $input.item.json || {};
let body = raw;
if (typeof raw.body === 'string') {
  try { body = JSON.parse(raw.body); } catch (e) { body = { ok: false, error: 'NON_JSON_RESPONSE', raw: raw.body.slice(0, 500) }; }
} else if (raw.body && typeof raw.body === 'object') {
  body = raw.body;
}

const validStatuses = ['PENDING_REVIEW', 'WAITING_HISTORY'];
const isSheetUrlValid = /^https:\/\/docs\.google\.com\/spreadsheets\/d\//.test(body.sheet_url || '');

if (body.ok !== true || !validStatuses.includes(body.status) || !body.sheet_id || !isSheetUrlValid) {
  return {
    json: {
      ok: false,
      report_status: 'REPORT_CREATION_FAILED',
      file_id: $('Validate 11 Fields').item.json.file_id,
      customer_id: $('Validate 11 Fields').item.json.id_pelanggan,
      technician: $('Validate 11 Fields').item.json.technician,
      error_detail: JSON.stringify(body).slice(0, 1000)
    }
  };
}

return {
  json: {
    ok: true,
    report_status: body.status,
    file_id: body.file_id,
    google_sheet_url: body.sheet_url,
    customer_name: body.customer_name,
    technician: body.technician,
    comparison_ready: body.comparison_ready,
    missing_periods: body.missing_periods || [],
    warnings: body.warnings || [],
    pdf_status: body.status === 'PENDING_REVIEW' ? 'WAITING_MANUAL_APPROVAL' : 'WAITING_HISTORY',
    message: 'Google Sheets created: ' + body.sheet_url
  }
};

const item = $input.item.json || {};
return {
  json: {
    processed_at: item.processed_at,
    file_id: item.file_id,
    file_name: item.file_name,
    submission_id: item.submission_id,
    technician: item.technician,
    ocr_status: item.ocr_status,
    validation_errors: (item.validation_errors || []).join('; '),
    raw_extracted: {
      id_pelanggan: item.id_pelanggan,
      nama_pelanggan: item.nama_pelanggan,
      jatuh_tempo_bulan: item.jatuh_tempo_bulan,
      jatuh_tempo_tahun: item.jatuh_tempo_tahun,
      total_harus_dibayar: item.total_harus_dibayar
    }
  }
};
